export default async function run(ctx) {
  await ctx.page.goto("__FX_URL__/mutator?layout=v2");

  const guards = [
    ctx.guard.url("mutator"),
    ctx.guard.exists(".feed-row", { timeout: 8000 }),
    ctx.guard.noDialog(),
  ];
  if (!(await ctx.guard.all(guards))) {
    return ctx.deopt(
      "Read every row of the feed as {text, url} and emit tweet.detected for each new one, deduplicated on its link.",
      { failed: await ctx.guard.failures() },
    );
  }

  const items = await ctx.page.evalExtract(".feed-row", {
    text: { selector: "[data-qa='post-body']" },
    url: { selector: "[data-qa='post-link']", attr: "href" },
  });
  if (items.length === 0) {
    return ctx.deopt("The feed rendered no rows where the recovered run saw some.", { rows: 0 });
  }

  for (const item of items) {
    await ctx.emitIfNew("tweet.detected", item, { dedupeKey: item.url });
  }
}
